     1	import { DispatchRun } from "../domain/notification";
     2	import { AlertPublisher } from "../messaging/eventPublisher";
     3	import { AlertConsumer } from "../notifier/consumerWorker";
     4	import { CustomerRepository } from "../repository/customerRepository";
     5	import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
     6	import { OrderRepository } from "../repository/orderRepository";
     7	import { planNotifications } from "./notificationPlanner";
     8	
     9	/** 발송 회차: 미발송 이벤트 → 알림 계획 → 발행(1배치) → 소비·문자 발송 → 회차 기록 */
    10	export class DispatchService {
    11	  private lastRunId = 0;
    12	
    13	  constructor(
    14	    private readonly orders: OrderRepository,
    15	    private readonly customers: CustomerRepository,
    16	    private readonly publisher: AlertPublisher,
    17	    private readonly consumer: AlertConsumer,
    18	    private readonly log: DeliveryLogRepository,
    19	  ) {}
    20	
    21	  runOnce(): DispatchRun {
    22	    const runId = ++this.lastRunId;
    23	    const events = this.orders.takePending();
    24	    const plan = planNotifications(events, this.customers);
    25	    const pub = this.publisher.publishRun(plan.notifications);
    26	    const drained = this.consumer.drain(runId);
    27	    const run: DispatchRun = {
    28	      runId,
    29	      planned: plan.notifications,
    30	      skippedOptOut: plan.skippedOptOut,
    31	      published: pub.accepted,
    32	      batch: pub.batch,
    33	      delivered: drained.delivered,
    34	      failed: drained.failed,
    35	    };
    36	    this.log.saveRun(run);
    37	    return run;
    38	  }
    39	}
=== src/report/dispatchReport.ts
     1	import { DispatchRun, KIND_LABEL } from "../domain/notification";
     2	import { CustomerRepository } from "../repository/customerRepository";
     3	import { maskMobile, normalizeMobile, padEnd } from "../util/format";
     4	
     5	export interface DispatchReportLine {
     6	  orderNo: string;
     7	  customerId: string;
     8	  kind: string;
     9	  status: "발송" | "미발송" | "실패";
    10	  to: string;
    11	}
    12	
    13	export interface DispatchReport {
    14	  runId: number;
    15	  batch: number;
    16	  planned: number;
    17	  published: number;
    18	  delivered: number;
    19	  failed: number;
    20	  skippedOptOut: number;
    21	  lines: DispatchReportLine[];
    22	  text: string;
    23	}
    24	
    25	/** 운영 화면용 회차 리포트 — 계획된 알림마다 발송 여부를 보여 준다. */
    26	export function buildDispatchReport(run: DispatchRun, customers: CustomerRepository): DispatchReport {
    27	  const lines: DispatchReportLine[] = run.planned.map((n) => {
    28	    const hit = run.delivered.find((d) => d.orderNo === n.orderNo && d.kind === n.kind);
    29	    const fail = run.failed.find((f) => f.orderNo === n.orderNo && f.kind === n.kind);
    30	    const phone = normalizeMobile(customers.find(n.customerId)?.phone ?? "") ?? "";
    31	    return {
    32	      orderNo: n.orderNo,
    33	      customerId: n.customerId,
    34	      kind: KIND_LABEL[n.kind],
    35	      status: hit ? "발송" : fail ? "실패" : "미발송",
    36	      to: maskMobile(phone),
    37	    };
    38	  });
    39	  const title = `회차 ${run.runId} (배치 ${run.batch}) 계획 ${run.planned.length} / 발행 ${run.published} / 발송 ${run.delivered.length} / 실패 ${run.failed.length} / 수신거부 ${run.skippedOptOut}`;
    40	  const body = lines.map((l) => `${padEnd(l.orderNo, 22)} ${padEnd(l.kind, 10)} ${padEnd(l.status, 6)} ${l.to}`);
    41	  return {
    42	    runId: run.runId,
    43	    batch: run.batch,
    44	    planned: run.planned.length,
    45	    published: run.published,
    46	    delivered: run.delivered.length,
    47	    failed: run.failed.length,
    48	    skippedOptOut: run.skippedOptOut,
    49	    lines,
    50	    text: [title, ...body].join("\n"),
    51	  };
    52	}

